-- Creating a table with a primary key (Clustered Index by default in InnoDB)
CREATE TABLE users (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    email VARCHAR(255) NOT NULL,
    created_at TIMESTAMP NOT NULL
);

-- Adding a non-clustered index to speed up reads on the email column
CREATE INDEX idx_users_email ON users(email);

-- A write operation (INSERT) now incurs the cost of updating both the clustered primary key tree and idx_users_email
INSERT INTO users (email, created_at) VALUES ('alice@example.com', NOW());
